mapper.select:
SELECT a.ID, a.DATASOURCE_NAME, a.TYPE, a.IP, a.PORT, b.ID as DATABASE_ID, b.DBNAME, b.USERNAME, b.PASSWORD, b.STATE, b.DRIVERCLASS_NAME, b.DATASOURCE_URL FROM seo.seo_datasource a LEFT JOIN seo.seo_datasource_database b on a.ID = b.SOURCE_ID where 1=1
AND a.ID = #{params.ID}
AND b.ID = #{params.DATABASE_ID}
AND a.DATASOURCE_NAME like '%${params.DATASOURCE_NAME}%'
AND b.DRIVERCLASS_NAME like '%${params.DRIVERCLASS_NAME}%'
AND b.DATASOURCE_URL like '%${params.DATASOURCE_URL}%'
AND a.TYPE = #{params.TYPE}
AND a.CREATE_TIME >= #{params.BEGIN_TIME}
AND a.CREATE_TIME <= #{params.END_TIME}
AND a.CREATE_USER = #{params.CREATE_USER}
AND b.STATE = #{params.STATE}
AND b.DBNAME like '%${params.DBNAME}%'
AND a.IP like '%${params.IP}%'
AND a.PORT like '%${params.PORT}%'
order by a.DATASOURCE_NAME,a.TYPE,a.IP,a.PORT,b.CREATE_TIME DESC LIMIT ${params.page},${params.rows}

SELECT count(*) FROM
seo.seo_datasource a LEFT JOIN  seo.seo_datasource_database b on a.ID = b.SOURCE_ID
where 1=1

    AND a.ID = #{params.ID}


    AND b.ID = #{params.DATABASE_ID}


    AND a.DATASOURCE_NAME like '%${params.DATASOURCE_NAME}%'


    AND b.DRIVERCLASS_NAME like '%${params.DRIVERCLASS_NAME}%'


    AND b.DATASOURCE_URL like '%${params.DATASOURCE_URL}%'


    AND a.TYPE = #{params.TYPE}


    AND a.CREATE_TIME >= #{params.BEGIN_TIME}


    AND a.CREATE_TIME <= #{params.END_TIME}


    AND a.CREATE_USER = #{params.CREATE_USER}


    AND b.STATE = #{params.STATE}


    AND b.DBNAME like '%${params.DBNAME}%'


    AND a.IP like '%${params.IP}%'


    AND a.PORT like '%${params.PORT}%'

SELECT a.ID, a.DATASOURCE_NAME, a.TYPE, a.IP, a.PORT, b.ID as DATABASE_ID, b.DBNAME, b.USERNAME, b.PASSWORD, b.STATE, b.DRIVERCLASS_NAME, b.DATASOURCE_URL, b.CREATE_TIME FROM seo.seo_datasource a LEFT JOIN seo.seo_datasource_database b on a.ID = b.SOURCE_ID where 1=1
AND a.ID = #{params.ID}
AND b.ID = #{params.DATABASE_ID}
AND a.DATASOURCE_NAME like '%${params.DATASOURCE_NAME}%'
AND b.DRIVERCLASS_NAME like '%${params.DRIVERCLASS_NAME}%'
AND b.DATASOURCE_URL like '%${params.DATASOURCE_URL}%'
AND a.TYPE = #{params.TYPE}
AND a.CREATE_TIME >= #{params.BEGIN_TIME}
AND a.CREATE_TIME <= #{params.END_TIME}
AND a.CREATE_USER = #{params.CREATE_USER}
AND b.STATE = #{params.STATE}
AND b.DBNAME like '%${params.DBNAME}%'
AND a.IP like '%${params.IP}%'
AND a.PORT like '%${params.PORT}%'
order by a.DATASOURCE_NAME,a.TYPE,a.IP,a.PORT,b.CREATE_TIME DESC

SELECT * FROM
seo.seo_datasource_database a
where 1=1

    AND a.SOURCE_ID = #{params.SOURCE_ID}


    AND a.DBNAME = #{params.DBNAME}

SELECT *
FROM
seo.seo_datasource a
where 1=1

    AND a.ID != #{params.ID}


    AND a.DATASOURCE_NAME = #{params.DATASOURCE_NAME}
